{
  "decline_reason": "",
  "claims": [
    {
      "text": "The statutory baseline is that the Registrar must examine and report on compliance with the Act and whether there are grounds for rejecting the application.",
      "quotes": [
        {
          "ref": "TMA1995/s31",
          "quote": "The Registrar must, in accordance with the regulations, examine and report on: (a) whether the application has been made in accordance with this Act; and (b) whether there are grounds under this Act for rejecting it."
        }
      ],
      "authority": "legislation"
    },
    {
      "text": "The Manual describes a quality management system that monitors, manages and reviews the ongoing suitability and efficiency of IP Australia’s processes and procedures.",
      "quotes": [
        {
          "ref": "TMM/Part1/2#1",
          "quote": "IP Australia’s quality management system, whilst monitoring, managing and reviewing the ongoing suitability and efficiency of our processes and procedures, also includes a strong focus on consistently delivering quality IP products and services."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "IP Australia uses Quality Standards as benchmarks to assess or review all aspects of trade mark examination work.",
      "quotes": [
        {
          "ref": "TMM/Part1/2#1",
          "quote": "As part of meeting the above objectives, a set of Quality Standards is applicable to all aspects of an examination of a trade mark application. They provide us IP Australia with benchmarks against which to assess (or review) the quality of the work we produced."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The search-strategy benchmark is whether the strategy would find all citations.",
      "quotes": [
        {
          "ref": "TMM/Part1/2#1",
          "quote": "TS1: The search strategy would find all citations."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The extract-list benchmark is whether it included all relevant signs that should be considered.",
      "quotes": [
        {
          "ref": "TMM/Part1/2#1",
          "quote": "TS2: The extract list included all relevant signs which should be considered."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "Examination reporting is assessed against the requirement to raise and maintain all valid objections.",
      "quotes": [
        {
          "ref": "TMM/Part1/2#1",
          "quote": "TE1: All valid objections are raised and maintained."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "Examination reporting is also assessed against the requirement not to raise or maintain invalid objections.",
      "quotes": [
        {
          "ref": "TMM/Part1/2#1",
          "quote": "TE2: Invalid objections are not raised or maintained."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The legal basis for an examination decision must be recorded and/or communicated under the quality standards.",
      "quotes": [
        {
          "ref": "TMM/Part1/2#1",
          "quote": "TE3: The legal basis for the decision is recorded and/or communicated."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The quality standards require clear and appropriate options for addressing objections to be identified and communicated.",
      "quotes": [
        {
          "ref": "TMM/Part1/2#1",
          "quote": "TE4: Clear and appropriate options to address objections are identified and communicated."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The record-keeping benchmark requires decision reasons to be recorded and all material or comments informing the decision to be on file.",
      "quotes": [
        {
          "ref": "TMM/Part1/2#1",
          "quote": "TR1: Reasons for any decisions are recorded and all material/comments which have informed the decision are on file."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The Manual supports implementation of these standards but remains a guide to be interpreted in the context of legislation and relevant court and tribunal decisions.",
      "quotes": [
        {
          "ref": "TMM/Part1/2#1",
          "quote": "The Manual is fundamental to implementing the quality standards, but must always be considered as a guide and interpreted in the context of the Act, Regulations and the relevant decisions of courts and tribunals."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The supplied passages do not specify who conducts quality reviews, how work is selected, how often reviews occur or what corrective action follows; they therefore do not establish the complete operational checking process.",
      "quotes": [],
      "authority": "none"
    }
  ],
  "declined": false,
